<?php
require_once 'config.php';require_admin($conn);
$counts=$conn->query("SELECT COUNT(*) AS total, SUM(CASE WHEN is_active=1 THEN 1 ELSE 0 END) AS active, SUM(CASE WHEN stock<=5 AND is_active=1 THEN 1 ELSE 0 END) AS low FROM products")->fetch_assoc();
$orders=$conn->query("SELECT COUNT(*) total, SUM(CASE WHEN payment_status='pending' THEN 1 ELSE 0 END) pending, SUM(CASE WHEN payment_status='completed' THEN total_price ELSE 0 END) revenue FROM orders")->fetch_assoc();
$users=(int)$conn->query('SELECT COUNT(*) n FROM users')->fetch_assoc()['n'];
$latest=$conn->query('SELECT id,name,total_products,total_price,placed_on,payment_status FROM orders ORDER BY id DESC LIMIT 6')->fetch_all(MYSQLI_ASSOC);
$low=$conn->query('SELECT id,name,stock FROM products WHERE stock<=5 AND is_active=1 ORDER BY stock,id LIMIT 6')->fetch_all(MYSQLI_ASSOC);
$pending=table_exists($conn,'product_reviews')?(int)$conn->query("SELECT COUNT(*) n FROM product_reviews WHERE status='pending'")->fetch_assoc()['n']:0;
?>
